const b=$input.first().json.body||{};
const L=['en','ar','hi','zh','ur','es'].includes(b.lang)?b.lang:'en';
const T={
  en: `Your week: you spent £${b.spent}. Safe to spend: £${b.safePerDay}/day. Tip: ${b.tip}`,
  ar: `أسبوعك: أنفقت £${b.spent}. المبلغ الآمن للإنفاق: £${b.safePerDay} يوميًا. نصيحة: ${b.tip}`,
  hi: `आपका सप्ताह: आपने £${b.spent} खर्च किए। सुरक्षित खर्च: £${b.safePerDay}/दिन। सुझाव: ${b.tip}`,
  zh: `本周你花了£${b.spent}。每天安全花费：£${b.safePerDay}。提示：${b.tip}`,
  ur: `آپ کا ہفتہ: آپ نے £${b.spent} خرچ کیے۔ روزانہ محفوظ خرچ: £${b.safePerDay}۔ مشورہ: ${b.tip}`,
  es: `Tu semana: gastaste £${b.spent}. Gasto seguro: £${b.safePerDay}/día. Consejo: ${b.tip}`
};
const D={"en": "Guidance, not regulated financial advice.", "ar": "إرشاد وليس نصيحة مالية منظمة.", "hi": "मार्गदर्शन, विनियमित वित्तीय सलाह नहीं।", "zh": "仅为指导，非受监管的财务建议。", "ur": "رہنمائی، منظم مالی مشورہ نہیں۔", "es": "Orientación, no asesoramiento financiero regulado."};
return [{json:{message:T[L]+' '+D[L],lang:L}}];
